mapper.select:
SELECT tmp.areaName, tmp.ypfl, tmp.yjsl, CONCAT(CAST(IF(ROUND(tmp.yjsl / tmp.ypfl * 100, 2) IS NULL, 0, ROUND(tmp.yjsl / tmp.ypfl * 100, 2)) AS CHAR),'%') AS yjszb, tmp.sdcl, tmp.plcl, tmp.zczngd, (tmp.sdcl + tmp.plcl + tmp.zczngd) AS zcgdhj, CONCAT(CAST(IF(ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.ypfl * 100, 2) IS NULL, 0, ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.ypfl * 100, 2)) AS CHAR),'%') AS zcgdzb, tmp.yhlw, tmp.gdcs, (tmp.yhlw + tmp.gdcs) AS ycgdhj, CONCAT(CAST(IF(ROUND((tmp.yhlw + tmp.gdcs) / tmp.ypfl * 100, 2) IS NULL, 0, ROUND((tmp.yhlw + tmp.gdcs) / tmp.ypfl * 100, 2)) AS CHAR),'%') AS ycgdzb, tmp.wjsl, tmp.gzl, CONCAT(CAST(IF(ROUND(tmp.wjsl / tmp.ypfl * 100, 2) IS NULL, 0, ROUND(tmp.wjsl / tmp.ypfl * 100, 2)) AS CHAR),'%') AS wjszb FROM ( SELECT
COALESCE(CASE WHEN area.type_ = '一级' THEN '省本级' ELSE area.name_ END, '未知') AS areaName,
COALESCE(CASE WHEN county.type_ = '二级' THEN CONCAT(county.name_,'市本级') ELSE county.name_ END, '未知') AS areaName,
COUNT(IF(a.status=1, TRUE, NULL)) AS ypfl, COUNT(IF(o.status_ = 'end', TRUE, NULL)) AS yjsl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND (o.batch_flag = 0 OR o.batch_flag IS NULL), TRUE, NULL)) AS sdcl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND o.batch_flag = 1, TRUE, NULL)) AS plcl, COUNT(IF(o.end_reason = '1', TRUE, NULL)) AS zczngd, COUNT(IF(o.end_reason = '2', TRUE, NULL)) AS yhlw, COUNT(IF(o.end_reason = '3', TRUE, NULL)) AS gdcs, COUNT(IF(o.status_ NOT IN ('end','tracking') OR o.status_ IS NULL, TRUE, NULL)) AS wjsl, COUNT(IF(o.status_ = 'tracking', TRUE, NULL)) AS gzl FROM maintenance_detail_new a LEFT JOIN sys_area area ON a.area_id = area.id_ LEFT JOIN sys_area county ON a.county_id = county.id_ LEFT JOIN topp_order o ON a.order_id = o.id_ WHERE a.status = 1
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND o.business_dep = #{businessDep}
AND a.area_id IS NOT NULL GROUP BY a.area_id ORDER BY area.order_ ASC
AND a.area_id IN #{id} GROUP BY a.county_id ORDER BY a.county_id ASC, area.order_ ASC
AND a.area_id IN #{id} AND a.county_id IN #{id} GROUP BY a.county_id ORDER BY county.order_ ASC
) tmp

SELECT tmp.areaName, tmp.ypfl, tmp.yjsl, CONCAT(CAST(IF(ROUND(tmp.yjsl / tmp.ypfl * 100, 2) IS NULL, 0, ROUND(tmp.yjsl / tmp.ypfl * 100, 2)) AS CHAR),'%') AS yjszb, tmp.sdcl, tmp.plcl, tmp.zczngd, (tmp.sdcl + tmp.plcl + tmp.zczngd) AS zcgdhj, CONCAT(CAST(IF(ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.ypfl * 100, 2) IS NULL, 0, ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.ypfl * 100, 2)) AS CHAR),'%') AS zcgdzb, tmp.yhlw, tmp.gdcs, (tmp.yhlw + tmp.gdcs) AS ycgdhj, CONCAT(CAST(IF(ROUND((tmp.yhlw + tmp.gdcs) / tmp.ypfl * 100, 2) IS NULL, 0, ROUND((tmp.yhlw + tmp.gdcs) / tmp.ypfl * 100, 2)) AS CHAR),'%') AS ycgdzb, tmp.wjsl, tmp.gzl, CONCAT(CAST(IF(ROUND(tmp.wjsl / tmp.ypfl * 100, 2) IS NULL, 0, ROUND(tmp.wjsl / tmp.ypfl * 100, 2)) AS CHAR),'%') AS wjszb FROM ( SELECT '全省' '合计' AS areaName, COUNT(IF(a.status=1, TRUE, NULL)) AS ypfl, COUNT(IF(o.status_ = 'end', TRUE, NULL)) AS yjsl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND (o.batch_flag = 0 OR o.batch_flag IS NULL), TRUE, NULL)) AS sdcl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND o.batch_flag = 1, TRUE, NULL)) AS plcl, COUNT(IF(o.end_reason = '1', TRUE, NULL)) AS zczngd, COUNT(IF(o.end_reason = '2', TRUE, NULL)) AS yhlw, COUNT(IF(o.end_reason = '3', TRUE, NULL)) AS gdcs, COUNT(IF(o.status_ NOT IN ('end','tracking') OR o.status_ IS NULL, TRUE, NULL)) AS wjsl, COUNT(IF(o.status_ = 'tracking', TRUE, NULL)) AS gzl FROM maintenance_detail_new a LEFT JOIN topp_order o ON a.order_id = o.id_ WHERE a.status = 1
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND o.business_dep = #{businessDep}
AND a.area_id IS NOT NULL
AND a.area_id IN #{id} AND a.county_id IS NOT NULL
AND a.area_id IN #{id} AND a.county_id IN #{id}
) tmp

SELECT tmp.areaName, tmp.countyName, tmp.managerName, tmp.gdl AS ypfl, tmp.yjsl, CONCAT(CAST(IF(ROUND(tmp.yjsl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.yjsl / tmp.gdl * 100, 2)) AS CHAR),'%') AS yjszb, tmp.sdcl, tmp.plcl, tmp.zczngd, (tmp.sdcl + tmp.plcl + tmp.zczngd) AS zcgdhj, CONCAT(CAST(IF(ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.gdl * 100, 2) IS NULL, 0, ROUND((tmp.sdcl + tmp.plcl + tmp.zczngd) / tmp.gdl * 100, 2)) AS CHAR),'%') AS zcgdzb, tmp.yhlw, tmp.gdcs, (tmp.yhlw + tmp.gdcs) AS ycgdhj, CONCAT(CAST(IF(ROUND((tmp.yhlw + tmp.gdcs) / tmp.gdl * 100, 2) IS NULL, 0, ROUND((tmp.yhlw + tmp.gdcs) / tmp.gdl * 100, 2)) AS CHAR),'%') AS ycgdzb, tmp.wjsl, tmp.gzl, CONCAT(CAST(IF(ROUND(tmp.wjsl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.wjsl / tmp.gdl * 100, 2)) AS CHAR),'%') AS wjszb FROM ( SELECT COALESCE(CASE WHEN area.type_ = '一级' THEN '省本级' ELSE area.name_ END, '未知') AS areaName, CASE WHEN county.type_ = '二级' THEN '市本级' ELSE county.name_ END AS countyName, u.name_ch AS managerName, COUNT(1) AS gdl, COUNT(IF(o.status_ = 'end', TRUE, NULL)) AS yjsl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND (o.batch_flag = 0 OR o.batch_flag IS NULL), TRUE, NULL)) AS sdcl, COUNT(IF(o.status_ = 'end' AND o.end_reason = '0' AND o.batch_flag = 1, TRUE, NULL)) AS plcl, COUNT(IF(o.end_reason = '1', TRUE, NULL)) AS zczngd, COUNT(IF(o.end_reason = '2', TRUE, NULL)) AS yhlw, COUNT(IF(o.end_reason = '3', TRUE, NULL)) AS gdcs, COUNT(IF(o.status_ NOT IN ('end','tracking') OR o.status_ IS NULL, TRUE, NULL)) AS wjsl, COUNT(IF(o.status_ = 'tracking', TRUE, NULL)) AS gzl FROM maintenance_detail_new a LEFT JOIN sys_area area ON a.area_id = area.id_ LEFT JOIN sys_area county ON a.county_id = county.id_ LEFT JOIN topp_order o ON a.order_id = o.id_ LEFT JOIN sys_user u ON u.id_ = a.user_id WHERE a.status = 1 AND a.user_id IS NOT NULL
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND a.area_id IN #{id}
AND a.county_id IN #{id}
AND a.manager_id = #{managerId}
AND u.name_ch LIKE CONCAT('%', #{managerName}, '%')
AND a.is_imp_prt = #{isImpPrt}
AND a.grp_type = #{grpType}
GROUP BY u.id_, a.area_id, a.county_id ORDER BY area.order_ ASC, county.order_ ASC, u.id_ ASC
LIMIT #{startRow}, #{pageSize}
) tmp

SELECT COUNT(1) FROM (
    SELECT u.id_
    FROM maintenance_detail_new a
    LEFT JOIN sys_area area ON a.area_id = area.id_
    LEFT JOIN sys_area county ON a.county_id = county.id_
    LEFT JOIN sys_user u ON u.id_ = a.user_id
    WHERE a.status = 1 AND a.user_id IS NOT NULL

        AND a.order_type = #{orderType}


        AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}


        AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}


        AND a.area_id IN
        #{id}


        AND a.county_id IN
        #{id}


        AND a.manager_id = #{managerId}


        AND u.name_ch LIKE CONCAT('%', #{managerName}, '%')


        AND a.is_imp_prt = #{isImpPrt}


        AND a.grp_type = #{grpType}

    GROUP BY u.id_, a.area_id, a.county_id
) t

SELECT tmp.areaName, tmp.gdl, tmp.khjll, tmp.ypfl, CONCAT(CAST(IF(ROUND(tmp.ypfl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.ypfl / tmp.gdl * 100, 2)) AS CHAR),'%') AS ypfzb, tmp.wpfl, CONCAT(CAST(IF(ROUND(tmp.wpfl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.wpfl / tmp.gdl * 100, 2)) AS CHAR),'%') AS wpfzb, tmp.wpfkhjll, tmp.areaId FROM ( SELECT
area.name_ AS areaName, a.area_id AS areaId,
county.name_ AS areaName, county.id_ AS areaId,
COUNT(1) AS gdl, COUNT(DISTINCT(a.manager_id), IF(a.manager_id != '' AND a.manager_id IS NOT NULL, TRUE, NULL)) AS khjll, COUNT(IF(a.status=1, TRUE, NULL)) AS ypfl, COUNT(IF(a.status=0, TRUE, NULL)) AS wpfl, COUNT(DISTINCT(a.manager_id), IF(a.status=0, TRUE, NULL)) AS wpfkhjll FROM maintenance_detail a LEFT JOIN sys_area area ON a.area_id = area.id_ LEFT JOIN sys_area county ON a.county_id = county.id_ LEFT JOIN topp_order o ON a.order_id = o.id_ WHERE 1=1
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND a.business_dep = #{businessDep}
AND a.is_imp_prt = #{isImpPrt}
AND a.grp_type = #{grpType}
GROUP BY a.area_id ORDER BY area.order_ IS NULL, area.order_ ASC
AND a.area_id IN #{id} AND a.county_id IS NOT NULL GROUP BY a.county_id ORDER BY a.county_id ASC, area.order_ ASC
AND a.area_id IN #{id} AND a.county_id IN #{id} GROUP BY a.county_id ORDER BY county.order_ ASC
) tmp

SELECT sc.name_ AS orderTypeName, area.name_ AS areaName, county.name_ AS countyName,
    a.cust_grp_id AS custGrpId, a.grp_code AS grpCode, a.grp_name AS grpName,
    sc1.name_ AS businessDepName, a.manager_id AS managerId, a.manager_name AS managerName,
    a.svc_num AS svcNum, a.id_ AS id
FROM maintenance_detail a
LEFT JOIN sys_code sc ON a.order_type = sc.code_ AND sc.setting_str3 = 'maintenance_order'
LEFT JOIN sys_code sc1 ON a.business_dep = sc1.code_ AND sc1.type_ = 'expandDep'
LEFT JOIN sys_area area ON a.area_id = area.id_
LEFT JOIN sys_area county ON a.county_id = county.id_
WHERE a.status = 0

    AND a.order_type = #{orderType}


    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}


    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}


    AND a.area_id IN
    #{id}


    AND a.county_id IN
    #{id}


    AND a.business_dep = #{businessDep}


    AND a.is_imp_prt = #{isImpPrt}


    AND a.grp_type = #{grpType}


    AND a.manager_id LIKE CONCAT('%', #{managerId}, '%')


    AND a.manager_name LIKE CONCAT('%', #{managerName}, '%')


    AND a.grp_name LIKE CONCAT('%', #{grpName}, '%')


    AND a.grp_code LIKE CONCAT('%', #{grpCode}, '%')


    AND a.cust_grp_id LIKE CONCAT('%', #{custGrpId}, '%')


    AND a.svc_num LIKE CONCAT('%', #{svcNum}, '%')

ORDER BY a.create_time DESC

    LIMIT #{startRow}, #{pageSize}

SELECT COUNT(1) FROM maintenance_detail a
WHERE a.status = 0
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND a.area_id IN #{id}
AND a.county_id IN #{id}
AND a.business_dep = #{businessDep}
AND a.is_imp_prt = #{isImpPrt}
AND a.grp_type = #{grpType}
AND a.manager_id LIKE CONCAT('%', #{managerId}, '%')
AND a.manager_name LIKE CONCAT('%', #{managerName}, '%')
AND a.grp_name LIKE CONCAT('%', #{grpName}, '%')
AND a.grp_code LIKE CONCAT('%', #{grpCode}, '%')
AND a.cust_grp_id LIKE CONCAT('%', #{custGrpId}, '%')
AND a.svc_num LIKE CONCAT('%', #{svcNum}, '%')

SELECT tmp.areaName, tmp.gdl, tmp.khjll, tmp.ypfl, CONCAT(CAST(IF(ROUND(tmp.ypfl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.ypfl / tmp.gdl * 100, 2)) AS CHAR),'%') AS ypfzb, tmp.wpfl, CONCAT(CAST(IF(ROUND(tmp.wpfl / tmp.gdl * 100, 2) IS NULL, 0, ROUND(tmp.wpfl / tmp.gdl * 100, 2)) AS CHAR),'%') AS wpfzb, tmp.wpfkhjll, tmp.areaId FROM ( SELECT '全省' '合计' AS areaName, 'all' AS areaId, COUNT(1) AS gdl, COUNT(DISTINCT(a.manager_id), IF(a.manager_id != '' AND a.manager_id IS NOT NULL, TRUE, NULL)) AS khjll, COUNT(IF(a.status=1, TRUE, NULL)) AS ypfl, COUNT(IF(a.status=0, TRUE, NULL)) AS wpfl, COUNT(DISTINCT(a.manager_id), IF(a.status=0, TRUE, NULL)) AS wpfkhjll FROM maintenance_detail a LEFT JOIN sys_area area ON a.area_id = area.id_ LEFT JOIN sys_area county ON a.county_id = county.id_ LEFT JOIN topp_order o ON a.order_id = o.id_ WHERE 1=1
AND a.order_type = #{orderType}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
AND a.business_dep = #{businessDep}
AND a.is_imp_prt = #{isImpPrt}
AND a.grp_type = #{grpType}
AND a.area_id IN #{id} AND a.county_id IS NOT NULL
AND a.area_id IN #{id} AND a.county_id IN #{id}
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number,
    CONCAT(CAST(IF(ROUND(tmp.number / tmp.yjl * 100, 2) IS NULL, 0, ROUND(tmp.number / tmp.yjl * 100, 2)) AS CHAR),'%') AS zb
FROM (
    SELECT COALESCE(CASE WHEN area.type_ = '一级' THEN '省本级' ELSE area.name_ END, '未知') AS areaName,
        COUNT(1) AS yjl,
        COUNT(IF(o.cur_innet_flag = '1', TRUE, NULL)) AS number
    FROM maintenance_detail a
    LEFT JOIN sys_area area ON a.area_id = area.id_
    LEFT JOIN topp_order o ON a.order_id = o.id_
    WHERE a.status = 1 AND a.order_type = 'mnp'
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND o.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
    GROUP BY a.area_id ORDER BY area.order_ ASC
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number,
    CONCAT(CAST(IF(ROUND(tmp.number / tmp.yjl * 100, 2) IS NULL, 0, ROUND(tmp.number / tmp.yjl * 100, 2)) AS CHAR),'%') AS zb
FROM (
    SELECT '全省合计' AS areaName,
        COUNT(1) AS yjl,
        COUNT(IF(o.cur_innet_flag = '1', TRUE, NULL)) AS number
    FROM maintenance_detail a
    LEFT JOIN topp_order o ON a.order_id = o.id_
    WHERE a.status = 1 AND a.order_type = 'mnp'
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND o.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number, 
FROM (
    SELECT

            COALESCE(CASE WHEN area.type_ = '一级' THEN '省本级' ELSE area.name_ END, '未知') AS areaName
            CASE WHEN us.name_ch IS NULL THEN '其他' ELSE us.name_ch END AS areaName
            COALESCE(CASE WHEN county.type_ = '二级' THEN CONCAT(county.name_,'市本级') ELSE county.name_ END, '未知') AS areaName

        , COUNT(1) AS yjl,



                , a.area_id AS areaId
                , a.county_id AS areaId


    FROM maintenance_detail a
    LEFT JOIN sys_user us ON a.user_id = us.id_
    LEFT JOIN sys_area area ON a.area_id = area.id_
    LEFT JOIN sys_area county ON a.county_id = county.id_
    LEFT JOIN topp_order o ON a.order_id = o.id_

    WHERE a.order_type = #{orderType}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND o.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
    AND a.status = #{isDistribute}

        GROUP BY a.area_id ORDER BY area.order_ IS NULL, area.order_ ASC
        GROUP BY a.county_id ORDER BY a.county_id ASC, area.order_ ASC
        GROUP BY a.user_id ORDER BY a.user_id DESC

) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number, 
FROM (
    SELECT

            '全省'
            '合计'
         AS areaName,
        COUNT(1) AS yjl,

    FROM maintenance_detail a
    LEFT JOIN topp_order o ON a.order_id = o.id_

    WHERE a.order_type = #{orderType}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') >= #{leftTime}
    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') <= #{rightTime}
    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND o.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
    AND a.status = #{isDistribute}
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number,
    CONCAT(CAST(IF(ROUND(tmp.number / tmp.yjl * 100, 2) IS NULL, 0, ROUND(tmp.number / tmp.yjl * 100, 2)) AS CHAR),'%') AS zb

        , IF(ROUND(tmp.xynf / 10000, 2) IS NULL, 0, ROUND(tmp.xynf / 10000, 2)) AS xynf


        , IF(ROUND(tmp.yjnsr / 10000, 2) IS NULL, 0, ROUND(tmp.yjnsr / 10000, 2)) AS yjnsr

FROM (
    SELECT
        '全省''合计' AS areaName
        , COUNT(1) AS yjl


                , COUNT(IF(a.exte_flag = 1, TRUE, NULL)) AS number, SUM(a.NEW_SCHEME_FEE) AS xynf


                , COUNT(IF(a.NEW_RED_CREATE_DATE != '', TRUE, NULL)) AS number


                , COUNT(IF(a.NEW_CONSUME_TIME IS NOT NULL, TRUE, NULL)) AS number, SUM(a.NEW_AMOUNT_PER_YEAR) AS yjnsr


    FROM (

    ) a
    WHERE 1 = 1
    AND a.status = #{isDistribute}
    AND a.create_time >= STR_TO_DATE(#{leftTime},'%Y-%m-%d')
    AND a.create_time < DATE_ADD(STR_TO_DATE(#{rightTime},'%Y-%m-%d'),INTERVAL 1 DAY)
    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND a.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number, FROM ( SELECT
COALESCE(CASE WHEN area.type_ = '一级' THEN '省本级' ELSE area.name_ END, '未知') AS areaName CASE WHEN us.name_ch IS NULL THEN '其他' ELSE us.name_ch END AS areaName COALESCE(CASE WHEN county.type_ = '二级' THEN CONCAT(county.name_,'市本级') ELSE county.name_ END, '未知') AS areaName
, COUNT(1) AS yjl,
FROM maintenance_detail a LEFT JOIN sys_user us ON a.user_id = us.id_ LEFT JOIN sys_area area ON a.area_id = area.id_ LEFT JOIN sys_area county ON a.county_id = county.id_ LEFT JOIN topp_order o ON a.order_id = o.id_
WHERE 1=1 AND a.order_type = #{orderType}
AND o.business_dep = #{businessDep} AND a.is_imp_prt = #{isImpPrt} AND a.grp_type = #{grpType} AND a.status = #{isDistribute}
GROUP BY a.area_id ORDER BY area.order_ IS NULL, area.order_ ASC AND a.area_id IN #{id} GROUP BY a.county_id ORDER BY a.county_id ASC, area.order_ ASC AND a.area_id IN #{id} AND a.county_id IN #{id} GROUP BY a.user_id ORDER BY a.user_id DESC
) tmp

SELECT tmp.areaName, tmp.yjl, tmp.number, 
FROM (
    SELECT
        '全省''合计' AS areaName,
        COUNT(1) AS yjl,

    FROM maintenance_detail a
    LEFT JOIN topp_order o ON a.order_id = o.id_

    WHERE 1=1 AND a.order_type = #{orderType}

    AND a.area_id IN #{id}
    AND a.county_id IN #{id}
    AND o.business_dep = #{businessDep}
    AND a.is_imp_prt = #{isImpPrt}
    AND a.grp_type = #{grpType}
    AND a.status = #{isDistribute}
) tmp

choose.when:
SELECT ttt.areaName, ttt.countryName, ttt.managerName, ttt.relationTel, ttt.warnCount, ttt.normalClose, ttt.abnormalClose, ttt.tracking, ttt.untreated, ttt.onlineCount, ttt.onlineRate, ttt.rank, ttt.user_id FROM ( SELECT 0 AS rank, CONCAT(CAST(IF(ROUND(tt.onlineCount * 1.0 / tt.warnCount * 100, 2) IS NULL, 0, ROUND(tt.onlineCount * 1.0 / tt.warnCount * 100, 2)) AS CHAR),'%') AS onlineRate, tt.* FROM (SELECT CASE WHEN a.type_ = '一级' THEN '省本级' WHEN a.type_ = '二级' THEN a.name_ WHEN a.type_ = '三级' THEN p.name_ ELSE '' END AS areaName, CASE WHEN a.type_ = '一级' THEN '' WHEN a.type_ = '二级' THEN '市本级' WHEN a.type_ = '三级' THEN a.name_ ELSE '' END AS countryName, u.name_ch AS managerName, u.name_ AS relationTel, COUNT(1) AS warnCount, COUNT(IF(t.status_ = 'end' AND t.end_reason IN ('0','1'), TRUE, NULL)) AS normalClose, COUNT(IF(t.status_ = 'end' AND t.end_reason IN ('2','3'), TRUE, NULL)) AS abnormalClose, COUNT(IF(t.status_ = 'tracking', TRUE, NULL)) AS tracking, COUNT(IF(t.status_ NOT IN ('end','tracking') OR t.status_ IS NULL, TRUE, NULL)) AS untreated, COUNT(IF(t.cur_innet_flag = '1', TRUE, NULL)) AS onlineCount, u.id_ AS user_id FROM maintenance_detail m LEFT JOIN topp_order t ON m.order_id = t.id_ LEFT JOIN sys_user u ON m.user_id = u.id_ LEFT JOIN sys_org o ON u.org_id = o.id_ LEFT JOIN sys_area a ON a.id_ = o.area_id LEFT JOIN sys_area p ON a.parent_ = p.id_ WHERE m.STATUS = 1 AND m.order_type = 'mnp' AND m.user_id IS NOT NULL AND DATE_FORMAT(m.create_time, '%Y-%m-%d') >= #{leftTime} AND DATE_FORMAT(m.create_time, '%Y-%m-%d') <= #{rightTime}
AND (a.id_ IN #{id} OR p.id_ IN #{id})
AND p.id_ IN #{id} AND a.id_ IN #{id}
